properties.Script_1:
// --------------------------------------------------------------------------------
// Cargar el combobox de estados añadiendo la opción Todos
// --------------------------------------------------------------------------------
importClass("VImage");

// --------------------------------------------------------------------------------
// Preparamos el control combobox
// --------------------------------------------------------------------------------
var combobox = theRoot.dataView().control("DSC");
combobox.clear()

// --------------------------------------------------------------------------------
// Añadimos la opción todos
// --------------------------------------------------------------------------------
//combobox.addItem(".");

// --------------------------------------------------------------------------------

// Seteamos la varialbe ID_ATB que obtenemos al seleccionar el atributo a cargar
var IdAtb = theRoot.varToString("ID_ATB_SEL");


// Preparamos el registro de opciones de atributos para hacer la lectura
var registroAtributo = new VRegisterList(theRoot);
registroAtributo.setTable("sygemat_corralon_dat/ATB_OPC");

var idRegistro = IdAtb;

registroAtributo.load("ATB", [idRegistro]);

registroAtributo.sort("ID");


	for(var i = 0; i < registroAtributo.size(); i++)
		{
			registroAtributo.sort(idRegistro);
			// Leemos los nombres de las opciones para cargarlos en el combobox D
			var registro = registroAtributo.readAt(i);
			var itemId = registro.fieldToInt("ID");
			var itemTexto = registro.fieldToString("OPC");
			//alert("el item id es: " + i + " el item text: " + itemTexto);
			// Añadimos la opción al combobox Descripcion
			combobox.addItem(itemTexto,itemId);
		}

// --------------------------------------------------------------------------------
// Si existe algo ya cargado, predefinimos en el combobox el valor
// --------------------------------------------------------------------------------
var Ididx = theRoot.varToString("ATB_OPC_GET");
theRoot.setVar("DSC", Ididx );
var index = combobox.findData(theRoot.varToString("DSC"));

combobox.setCurrentIndex(index);

// Leer la opción seleccionada del combobox Descripcion y guardarla en la variable local del formulario
theRoot.setVar("DSC", "");
var combobox = theRoot.dataView().control("DSC");
var itemId = combobox.itemData(combobox.currentIndex);
var findData = combobox.findData(itemId);
var itemText = combobox.itemText(findData);

//alert("LEER el item id es: " + itemId + " LEER el item text: " + itemText);

if (itemText)
{
	theRoot.setVar("DSC", itemText);

	//Seteo el id de variable para que cargue la opcion correcta
	theRoot.setVar("ID_DSC", itemId);

};
